import React, { useState, useEffect } from 'react';
import { Menu, X, Home, Music, TrendingUp, BookOpen, Sparkles,
         Upload, LayoutDashboard, Settings, LogOut, Shield, Heart, Bookmark } from 'lucide-react';
import './NavMobile.css';

const STORAGE_KEY = 'varim_nouvelles_';

function NavMobile({ utilisateur, allerVers, handleDeconnexion }) {
  const [ouvert, setOuvert] = useState(false);
  const [aNouveautes, setANouveautes] = useState(false);

  // Vérifier s'il y a des nouvelles publications depuis la dernière visite
  useEffect(() => {
    if (!utilisateur) return;

    const verifierNouveautes = () => {
      const badge = localStorage.getItem(STORAGE_KEY + utilisateur.id);
      setANouveautes(badge === 'true');
    };

    verifierNouveautes();

    // Écouter les mises à jour du badge
    window.addEventListener('varim_badge_update', verifierNouveautes);
    return () => window.removeEventListener('varim_badge_update', verifierNouveautes);
  }, [utilisateur]);

  // Vérifier les nouvelles publications en arrière-plan
  useEffect(() => {
    if (!utilisateur) return;

    const verifierPublications = async () => {
      try {
        const derniereVisite = localStorage.getItem('varim_nouveautes_derniere_visite_' + utilisateur.id);
        if (!derniereVisite) return;

        const res = await fetch(`/api/musiques/suivis/${utilisateur.id}`);
        const data = await res.json();
        const musiques = data.musiques || [];

        const aNouvellesPublications = musiques.some(
          m => new Date(m.date_ajout) > new Date(derniereVisite)
        );

        if (aNouvellesPublications) {
          localStorage.setItem(STORAGE_KEY + utilisateur.id, 'true');
          setANouveautes(true);
          window.dispatchEvent(new Event('varim_badge_update'));
        }
      } catch {}
    };

    verifierPublications();
    const interval = setInterval(verifierPublications, 5 * 60 * 1000); // toutes les 5 min
    return () => clearInterval(interval);
  }, [utilisateur]);

  const naviguer = (page) => {
    allerVers(page);
    setOuvert(false);
  };

  return (
    <>
      {/* BOUTON HAMBURGER avec point rouge */}
      <button className="hamburger" onClick={() => setOuvert(true)}>
        <Menu size={24} />
        {aNouveautes && <span className="hamburger-badge" />}
      </button>

      {ouvert && (
        <div className="nav-mobile-overlay" onClick={() => setOuvert(false)}>
          <div className="nav-mobile-menu" onClick={e => e.stopPropagation()}>
            <div className="nav-mobile-header">
              <span className="nav-mobile-logo">Varim Music</span>
              <button className="nav-mobile-fermer" onClick={() => setOuvert(false)}>
                <X size={22} />
              </button>
            </div>

            {utilisateur && (
              <div className="nav-mobile-user">
                <div className="nav-mobile-avatar">
                  {utilisateur.photo_profil
                    ? <img src={utilisateur.photo_profil} alt={utilisateur.prenom} />
                    : <span>{utilisateur.prenom[0].toUpperCase()}</span>
                  }
                </div>
                <div>
                  <p className="nav-mobile-nom">{utilisateur.prenom}</p>
                  <p className="nav-mobile-role">{utilisateur.role}</p>
                </div>
              </div>
            )}

            <div className="nav-mobile-liens">
              <button className="nav-mobile-lien" onClick={() => naviguer('accueil')}>
                <Home size={18} /> Accueil
              </button>
              <button className="nav-mobile-lien" onClick={() => naviguer('catalogue')}>
                <Music size={18} /> Catalogue
              </button>

              {/* NOUVEAUTÉS avec point rouge si abonné */}
              {utilisateur ? (
                <button className="nav-mobile-lien" onClick={() => naviguer('nouveautes')}>
                  <span className="nav-lien-ic-wrapper">
                    <Sparkles size={18} />
                    {aNouveautes && <span className="nav-lien-badge" />}
                  </span>
                  Nouveautés
                  {aNouveautes && <span className="nav-lien-badge-label">Nouveau</span>}
                </button>
              ) : (
                <button className="nav-mobile-lien" onClick={() => naviguer('login')}>
                  <Sparkles size={18} /> Nouveautés
                </button>
              )}

              <button className="nav-mobile-lien" onClick={() => naviguer('topventes')}>
                <TrendingUp size={18} /> Top Ventes
              </button>

              {utilisateur && (
                <button className="nav-mobile-lien nav-mobile-lien-favoris" onClick={() => naviguer('favoris')}>
                  <Heart size={18} /> Mes Favoris
                </button>
              )}

              {utilisateur && (
                <button className="nav-mobile-lien nav-mobile-lien-enregistrements" onClick={() => naviguer('enregistrements')}>
                  <Bookmark size={18} /> Mes Enregistrements
                </button>
              )}

              {utilisateur && utilisateur.role === 'acheteur' && (
                <button className="nav-mobile-lien" onClick={() => naviguer('bibliotheque')}>
                  <BookOpen size={18} /> Ma Bibliothèque
                </button>
              )}

              {utilisateur && utilisateur.role === 'artiste' && (
                <>
                  <button className="nav-mobile-lien nav-mobile-lien-publier" onClick={() => naviguer('upload')}>
                    <Upload size={18} /> Publier une musique
                  </button>
                  <button className="nav-mobile-lien" onClick={() => naviguer('dashboard')}>
                    <LayoutDashboard size={18} /> Mon Dashboard
                  </button>
                  <button className="nav-mobile-lien" onClick={() => naviguer('mon-compte')}>
                    <Settings size={18} /> Mon Compte
                  </button>
                  <button className="nav-mobile-lien" onClick={() => naviguer('bibliotheque')}>
                    <BookOpen size={18} /> Ma Bibliothèque
                  </button>
                </>
              )}

              {utilisateur && utilisateur.role === 'admin' && (
                <button className="nav-mobile-lien" onClick={() => naviguer('admin')}>
                  <Shield size={18} /> Panel Admin
                </button>
              )}
            </div>

            <div className="nav-mobile-bas">
              {!utilisateur ? (
                <>
                  <button className="nav-mobile-btn-connexion" onClick={() => naviguer('login')}>
                    Se connecter
                  </button>
                  <button className="nav-mobile-btn-inscription" onClick={() => naviguer('register')}>
                    S'inscrire
                  </button>
                </>
              ) : (
                <button className="nav-mobile-deconnexion" onClick={() => { handleDeconnexion(); setOuvert(false); }}>
                  <LogOut size={18} /> Déconnexion
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </>
  );
}

export default NavMobile;
